+func (s *Service) addUidToPushed(address string, uid uint32) {
+	s.pushedMu.Lock()
+	defer s.pushedMu.Unlock()
+	s.pushed[address] = uid
+}
+
+func (s *Service) getUidFromPushed(address string) (uint32, error) {
+	s.pushedMu.Lock()
+	defer s.pushedMu.Unlock()
+	if uid, ok := s.pushed[address]; ok {
