func getCols(line string) (prefix string, cols []string, suffix string) {
	cols = strings.SplitN(line, "(", 2)

	prefix = cols[0] + "("
	suffix = cols[1]
	cols = strings.SplitN(suffix, ")", 2)
	suffix = ")" + cols[1]
	cols = strings.Split(cols[0], ", ")

	return prefix, cols, suffix
}

