func sanitizeFilename(s string) (r string) {
	const allowedRunes = `_-.`
	return strings.Map(func(rv rune) rune {
		if unicode.IsLetter(rv) || unicode.IsNumber(rv) {
			return rv
		}
		if strings.ContainsRune(allowedRunes, rv) {
			return rv
		}
		return '_'
	}, s)
}

