	}
}

func (n *testingNetwork) finishAllMulticast() {
	n.mu.Lock()
	defer n.mu.Unlock()
	for i := 0; i < len(n.monitors); i++ {
		n.monitors[nodeID(i)].dec(networkCoserviceType)
	}
}

