// as a bson.D (list of key-value pairs).
func (c *collection) filtersToBSON(fs []driver.Filter) (bson.D, error) {
	filter := bson.D{} // must be a zero-length slice, not nil
	for _, f := range fs {
		bf, err := c.filterToBSON(f)
		if err != nil {
			return nil, err
		}
		filter = append(filter, bf)
	}
	return filter, nil
}

