}

// GetInt returns the integer of the field, or error if not defined
func (r *RunConfig) GetInt(field string) (int, error) {
	val := r.Get(field)
	if val == "" {
		return 0, errors.New("Didn't find " + field)
	}
	ret, err := strconv.Atoi(val)
	return ret, err
}

