func (s *feldmanVSSQualState) HandleBroadcastMsg(orig int, msg []byte) error {
	if !s.running {
		return errors.New("dkg is not running")
	}

	if orig >= s.Size() || orig < 0 {
		return fmt.Errorf("wrong origin input, should be less than %d, got %d",
