//export AddNamedOutputPost
func AddNamedOutputPost(cPackage uintptr, cTarget, cName, cOut *C.char) *C.char {
	target, err := getTargetPost(cPackage, cTarget)
	if err != nil {
		return C.CString(err.Error())
	}
