func NewBatchedDatabase(name string, root *doltdb.RootValue, ddb *doltdb.DoltDB, rs *env.RepoState) *Database {
	return &Database{
		name:      name,
		root:      root,
		ddb:       ddb,
		rs:        rs,
		batchMode: batched,
		tables:    make(map[string]*DoltTable),
	}
}

