		assert.Contains(t, stderr, er.Stderr,
			fmt.Sprintf("stderr %q should contain %q", stderr, er.Stderr))
	}
}

func (er ExecRun) exec() (string, string, int, error) {
	cmd := exec.Command("sh", "-c", er.Command)

	stdout := &bytes.Buffer{}
	stderr := &bytes.Buffer{}

	cmd.Stdout = stdout
	cmd.Stderr = stderr
	cmd.Dir = er.Dir
	cmd.Env = os.Environ()

