func addLeadingSlash(s string) string {
	if strings.HasPrefix(s, "/") {
		return s
	}
	return "/" + s
}

func removeTrailingIndexHTML(s string) string {
	if strings.HasSuffix(s, "/index.html") {
		return strings.TrimSuffix(s, "index.html")
	}
	return s
}

